"""Coin Change II — count combinations, so coins form the outer loop.

Iterating coins outside amounts counts each multiset once; swapping the loops
would count permutations instead.

Time: O(amount * len(coins))   Space: O(amount)
"""
from typing import List


class Solution:
    def change(self, amount: int, coins: List[int]) -> int:
        ways = [1] + [0] * amount
        for coin in coins:
            for value in range(coin, amount + 1):
                ways[value] += ways[value - coin]
        return ways[amount]
